import React, { useState } from 'react';
import { motion } from 'framer-motion';
import './Itinerary.css';

const Itinerary = () => {
  const [activeDay, setActiveDay] = useState(1);

  const itineraryData = [
    {
      day: 1,
      title: "Delhi Departure",
      description: "Begin your journey from Delhi with a scenic drive through the Himalayas.",
      image: "https://images.unsplash.com/photo-1587135941948-670b381f08ce?ixlib=rb-4.0.3&auto=format&fit=crop&w=1000&q=80"
    },
    {
      day: 2,
      title: "Chandigarh Sightseeing",
      description: "Explore the beautiful city of Chandigarh, known for its architecture and gardens.",
      image: "https://images.unsplash.com/photo-1593691509543-c55fb32d8de5?ixlib=rb-4.0.3&auto=format&fit=crop&w=1000&q=80"
    },
    {
      day: 3,
      title: "Manali Arrival",
      description: "Arrive in Manali and enjoy the breathtaking views of the valley.",
      image: "https://images.unsplash.com/photo-1506905925346-21bda4d32df4?ixlib=rb-4.0.3&auto=format&fit=crop&w=1000&q=80"
    },
    {
      day: 4,
      title: "Manali Exploration",
      description: "Visit Hadimba Temple, Vashisht Hot Springs, and enjoy local cuisine.",
      image: "https://images.unsplash.com/photo-1544008230-ac1e1fb4f4f9?ixlib=rb-4.0.3&auto=format&fit=crop&w=1000&q=80"
    },
    {
      day: 5,
      title: "Rohtang Pass Adventure",
      description: "Experience the thrill of Rohtang Pass with snow activities and panoramic views.",
      image: "https://images.unsplash.com/photo-1506905925346-21bda4d32df4?ixlib=rb-4.0.3&auto=format&fit=crop&w=1000&q=80"
    },
    {
      day: 6,
      title: "Return to Delhi",
      description: "Reluctant farewell to the mountains as you head back to Delhi.",
      image: "https://images.unsplash.com/photo-1587135941948-670b381f08ce?ixlib=rb-4.0.3&auto=format&fit=crop&w=1000&q=80"
    }
  ];

  return (
    <section className="itinerary">
      <motion.h2
        initial={{ opacity: 0, y: 50 }}
        whileInView={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.8 }}
        className="itinerary-title"
      >
        Your Futuristic Itinerary
      </motion.h2>
      <div className="itinerary-container">
        <div className="itinerary-days">
          {itineraryData.map((item) => (
            <motion.button
              key={item.day}
              className={`day-button ${activeDay === item.day ? 'active' : ''}`}
              onClick={() => setActiveDay(item.day)}
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              initial={{ opacity: 0, x: -50 }}
              whileInView={{ opacity: 1, x: 0 }}
              transition={{ duration: 0.5, delay: item.day * 0.1 }}
            >
              Day {item.day}
            </motion.button>
          ))}
        </div>
        <motion.div
          key={activeDay}
          initial={{ opacity: 0, x: 50 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.5 }}
          className="itinerary-content"
        >
          <div className="content-image">
            <img src={itineraryData[activeDay - 1].image} alt={itineraryData[activeDay - 1].title} />
          </div>
          <div className="content-text">
            <h3>{itineraryData[activeDay - 1].title}</h3>
            <p>{itineraryData[activeDay - 1].description}</p>
          </div>
        </motion.div>
      </div>
    </section>
  );
};

export default Itinerary;
